/// <summary>
/// PaffH 24.02.21
/// </summary>
public class NDXSetupPlaningOfRessourcesFormHandler
{
    FormRun formRunCaller;
    FormListBoxControl listboxInfo;
    List listInfo;
    int counter;
    int maxListInfo, resizeListInfo;
    ProdId lastProdId;
    int lastCountProdRec;
    ImageListAppl_Prod imageList;
    FormDataSource  ProdTable_DS;
    FormDataSource  ProdTable_2_DS;


}

Method.Source:
/// <summary>
/// PaffH 24.02.21
/// </summary>
/// <param name = "_element">FormRun</param>
protected void new(FormRun _element)
{
    this.InitFromFormRun(_element);
    listInfo = new List(Types::String);
    counter = 0;
    maxListInfo = 1100;
    resizeListInfo = 1000;
    imageList = new ImageListAppl_Prod();
}

/// <summary>
/// PaffH 24.02.21
/// </summary>
/// <param name = "_formRun">FormRun</param>
protected void InitFromFormRun(FormRun _formRun)
{
    formRunCaller = _formRun;
    ProdTable_DS = formRunCaller.dataHelper().FindDataSource(formDataSourceStr(NDXSetupPlaningOfRessources,ProdTable ));
    ProdTable_2_DS = formRunCaller.dataHelper().FindDataSource(formDataSourceStr(NDXSetupPlaningOfRessources,ProdTable_2 ));
}

/// <summary>
/// PaffH 02.03.21
/// </summary>
/// <param name = "_ProdTable_DS">FormDataSource</param>
public void setDataSourceProdTable(FormDataSource _ProdTable_DS)
{
    ProdTable_DS = _ProdTable_DS;
}

/// <summary>
/// PaffH 02.03.21
/// </summary>
/// <param name = "_ProdTable_2_DS">FormDataSource</param>
public void setDataSourceProdTable_2(FormDataSource _ProdTable_2_DS)
{
    ProdTable_2_DS = _ProdTable_2_DS;
}

/// <summary>
/// PaffH 02.03.21
/// timeout function in form NDXSetupPlaningOfRessources
/// check for new production orders
/// </summary>
public void fillListInfo()
{
    ProdId prodId;
    int lLastCountProdRec;

    if (formRunCaller.closed())
    {
        return;
    }
    if (listInfo.elements() > maxListInfo)
    {
        ListEnumerator enum = listInfo.getEnumerator();
        int anz = 0;
        List listInfo2 = new List(Types::String);
        while (enum.moveNext())
        {
            ++anz;
            listInfo2.addEnd(enum.current());
            if (anz > resizeListInfo)
            {
                break;
            }
        }
        listInfo = new List(Types::String);
        ListboxInfo.clear();
        enum = listInfo2.getEnumerator();
        while (enum.moveNext())
        {
            listInfo.addEnd(enum.current());
            ListBoxInfo.add(enum.current());
        }
    }
    ++counter;
    str infoTxt = strFmt("@NDX:NDXPlaceHolder02", NDXHelperCommon::seconds2Str());
    [prodId, lLastCountProdRec] = ProdTable::NDXGetLastProdId();
    if (prodId != lastProdId)
    {
        if (lLastCountProdRec - lastCountProdRec == 1)
        {
            infoTxt += "@NDX:NDX1NewPO";
        }
        else
        {
            infoTxt += strfmt("@NDX:NDXXNewPO", lLastCountProdRec - lastCountProdRec);
        }
        if (ProdTable_DS)
        {
            ProdTable_DS.executeQuery();
        }
        if (ProdTable_2_DS)
        {
            ProdTable_2_DS.executeQuery();
        }
        lastProdId = prodId;
        lastCountProdRec = lLastCountProdRec;
    }
    else
    {
        infoTxt += "@NDX:NDXNoChange";
    }

    listInfo.addStart(infoTxt);
    ListboxInfo.insert(infoTxt, 0);
}

/// <summary>
/// PaffH 24.02.21
/// </summary>
/// <param name = "_element">FormRun</param>
/// <returns>NDXSetupPlaningOfRessourcesFormHandler</returns>
static NDXSetupPlaningOfRessourcesFormHandler construct(FormRun _element)
{
    NDXSetupPlaningOfRessourcesFormHandler nDXSetupPlaningOfRessourcesFormHandler = new NDXSetupPlaningOfRessourcesFormHandler(_element);
    return nDXSetupPlaningOfRessourcesFormHandler;
}

/// <summary>
/// PaffH 01.03.21
/// </summary>
/// <param name = "_listBoxInfo">FormListBoxControl</param>
void ctrlListBoxInfo(FormListBoxControl _listBoxInfo)
{
    listboxInfo = _listBoxInfo;
}

